<?php $statusLabels = ['pending' => 'Pending', 'confirmed' => 'Confirmed', 'completed' => 'Completed', 'cancelled' => 'Cancelled', 'no_show' => 'No Show']; $isEdit = $section === 'appointments-edit'; ?>
<div class="customer-modal-backdrop" role="presentation"><section class="customer-modal appointment-modal" role="dialog" aria-modal="true" aria-labelledby="appointment-form-title"><div class="customer-modal-header"><div><span class="modal-eyebrow">Workshop schedule</span><h2 id="appointment-form-title"><?= $isEdit ? 'Edit Appointment' : 'Add Appointment' ?></h2><span class="modal-code"><?= $isEdit ? 'Update appointment details' : 'Schedule a customer visit' ?></span></div><a class="customer-modal-close" href="index.php?page=admin&amp;section=appointments" aria-label="Close">&times;</a></div><div class="customer-modal-body"><?php if ($errors): ?><div class="alert alert-danger"><?php foreach ($errors as $error): ?><div><?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><form method="post" action="index.php?page=admin&amp;section=<?= e($section) ?>&amp;id=<?= (int) $id ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Customer *</label><select class="form-select" name="customer_id" id="appointment-customer" required><option value="">Select customer</option><?php foreach ($customers as $customer): ?><option value="<?= (int) $customer['id'] ?>" <?= $input['customer_id'] === (int) $customer['id'] ? 'selected' : '' ?>><?= e($customer['name'] . ' (' . $customer['contact_number'] . ')') ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Vehicle</label><select class="form-select" name="vehicle_id" id="appointment-vehicle"><option value="0">No vehicle selected</option><?php foreach ($vehicles as $vehicle): ?><option data-customer-id="<?= (int) $vehicle['customer_id'] ?>" value="<?= (int) $vehicle['id'] ?>" <?= $input['vehicle_id'] === (int) $vehicle['id'] ? 'selected' : '' ?>><?= e($vehicle['vehicle_number'] . ' - ' . trim(($vehicle['make'] ?: '') . ' ' . ($vehicle['model'] ?: ''))) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Appointment Date *</label><input class="form-control" type="date" name="appointment_date" value="<?= e($input['appointment_date']) ?>" required></div><div class="col-md-6"><label class="form-label">Appointment Time *</label><input class="form-control" type="time" name="appointment_time" value="<?= e($input['appointment_time']) ?>" required></div><div class="col-md-8"><label class="form-label">Requested Service *</label><input class="form-control" name="requested_service" value="<?= e($input['requested_service']) ?>" placeholder="e.g. Full service, oil change" required></div><div class="col-md-4"><label class="form-label">Status *</label><select class="form-select" name="status" required><?php foreach ($statusLabels as $value => $label): ?><option value="<?= e($value) ?>" <?= $input['status'] === $value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="3" placeholder="Optional appointment notes"><?= e($input['notes']) ?></textarea></div></div><div class="customer-modal-footer px-0 pb-0"><a class="btn btn-light" href="index.php?page=admin&amp;section=appointments">Cancel</a><button class="btn btn-primary" type="submit"><?= $isEdit ? 'Update Appointment' : 'Save Appointment' ?></button></div></form></div></section></div>
<script>document.addEventListener('DOMContentLoaded',function(){const c=document.getElementById('appointment-customer'),v=document.getElementById('appointment-vehicle');if(!c||!v)return;function filter(){const id=c.value;Array.from(v.options).forEach(function(o){if(!o.dataset.customerId)return;o.hidden=!!id&&o.dataset.customerId!==id;if(o.hidden&&o.selected)v.value='0';});}c.addEventListener('change',filter);filter();});</script>
